"""Builds appendix_tests.tex and tables/layer_tests_numbers.json: tests between pairs of tested layers with the VLM at K = 2.
Source: runs/layer_vlm_k2/layer_pairs (repo/layer_pairs_k2.py). No request is sent.
The analyses by depth group (early, middle, late thirds) were removed from the paper on 2026-11-16: the VLM was not run on
all groups, so they are not reported.
Usage: python tools/make_layer_tests.py [RUN_DIR]     (default ../../code/ageval-dinov2-pilot/runs/layer_vlm_k2)
"""
import json, os, sys
import pandas as pd

HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); RUN = sys.argv[1] if len(sys.argv) > 1 else os.path.join(HERE, "runs", "layer_vlm_k2")
ENC = ["ResNet50", "ViT", "CLIP", "FLAVA", "SigLIP2", "Qwen3VL", "DINOv2", "BioCLIP", "DINOv3"]; MAIN = ENC[:6]
NM = {"ViT": "ViT", "DINOv2": "DINOv2", "CLIP": "CLIP", "ResNet50": "ResNet-50", "SigLIP2": "SigLIP 2", "BioCLIP": "BioCLIP", "DINOv3": "DINOv3", "Qwen3VL": "Qwen3-VL tower", "FLAVA": "FLAVA"}
sg = lambda v, d=1: ("$+$" if v >= 0 else "$-$") + f"{abs(v):.{d}f}"
LP = pd.read_csv(os.path.join(RUN, "layer_pairs", "all_comparisons.csv")); LP = LP[LP.family == "layer_vs_layer"]; ES = pd.read_csv(os.path.join(RUN, "layer_pairs", "encoder_summary.csv")).set_index("encoder")
ln = lambda l: str(int(l.split("_")[1]))
N = {"layer_pairs": {e: {"pairs": int((LP.encoder == e).sum()), "raw_p_below_0.05": int(((LP.encoder == e) & (LP.mcnemar_exact_p < 0.05)).sum()), "holm_within_below_0.05": int(((LP.encoder == e) & (LP.holm_within_encoder < 0.05)).sum()),
                         "holm_global_below_0.05": int(((LP.encoder == e) & (LP.holm_global < 0.05)).sum()), "range_pp": round(float(ES.loc[e].range_pp), 2)} for e in ENC}}
json.dump(N, open(os.path.join(HERE, "tables", "layer_tests_numbers.json"), "w"), indent=1)
A = ["% generated by tools/make_layer_tests.py; do not edit by hand", "\\section{Statistical tests between pairs of tested layers}", "\\label{app:tests}", "",
     "This appendix provides the statistical tests behind RQ4. The tests utilize the saved answers of the VLM in the 2-shot setting on the 500 queries (Appendix~\\ref{app:vlm}); no further request was sent. The analysis is exploratory, and every comparison is made within one encoder. The six encoders of the main text are listed first.", "",
     "For each encoder, the five tested layers result in ten pairs. We compare each pair using a two-sided exact McNemar test, a paired bootstrap interval over queries (10{,}000 replicates, resampled within dataset), and a Holm correction over the ten pairs of the encoder. "
     f"Of the {len(LP)} pairs of the nine encoders, {int((LP.mcnemar_exact_p < 0.05).sum())} have $p<0.05$ before the correction, {int((LP.holm_within_encoder < 0.05).sum())} after the correction within the encoder, and {int((LP.holm_global < 0.05).sum())} after a correction over all pairs. "
     "The layer with the highest accuracy is not separated from the runner-up in any encoder. Note that a difference that is not significant does not show that two layers are equal.", "",
     "\\begin{table*}[t]", "\\centering", "\\caption{\\textbf{Pairs of tested layers with the VLM, two references.} Highest block, runner-up and their difference with the unadjusted 95\\% interval; range of the five blocks; pairs that stay significant after a Holm correction within the encoder (higher block first). 500 queries.}", "\\label{tab:app-pairs}", "\\scriptsize", "\\setlength{\\tabcolsep}{3.4pt}",
     "\\begin{tabular}{@{}llcccccl@{}}", "\\toprule", "Encoder & Tested blocks & Highest & Runner-up & Difference (95\\% CI) & Range & Pooled & Significant pairs (Holm $p$) \\\\", "\\midrule"]
for e in ENC:
    s = ES.loc[e]; g = LP[(LP.encoder == e) & (LP.holm_within_encoder < 0.05)]
    sp = "; ".join((f"{ln(r.A)} $>$ {ln(r.B)}" if r.diff_A_minus_B_pp > 0 else f"{ln(r.B)} $>$ {ln(r.A)}") + f" ({r.holm_within_encoder:.3f})" for r in g.itertuples()) or "none"
    A.append(f"{NM[e]} & {s.layers_tested.replace(' ', ', ')} & {int(s.highest_observed_layer)} ({s.accuracy:.1f}) & {int(s.runner_up)} ({s.runner_up_accuracy:.1f}) & {sg(s.gap_pp)} ({sg(s.gap_ci95_lo_unadjusted)} to {sg(s.gap_ci95_hi_unadjusted)}) & {s.range_pp:.1f} & {s.pooled_accuracy:.1f} & {sp} \\\\" + ("\\addlinespace[2pt]" if e == MAIN[-1] else ""))
A += ["\\bottomrule", "\\end{tabular}", "\\end{table*}", ""]
open(os.path.join(HERE, "appendix_tests.tex"), "w").write("\n".join(A) + "\n"); print({e: N["layer_pairs"][e] for e in MAIN})
